import{_ as e,o as a,c as o,a2 as l}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"护城河 Moat","description":"巴菲特的\\"经济护城河\\"理论：企业持续竞争优势的终极来源","frontmatter":{"title":"护城河 Moat","description":"巴菲特的\\"经济护城河\\"理论：企业持续竞争优势的终极来源"},"headers":[],"relativePath":"02_concepts/moat.md","filePath":"02_concepts/moat.md"}'),r={name:"02_concepts/moat.md"};function h(p,t,s,n,i,d){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="护城河-moat" tabindex="-1">护城河 Moat <a class="header-anchor" href="#护城河-moat" aria-label="Permalink to &quot;护城河 Moat&quot;">​</a></h1><blockquote><p>在<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的投资词典里，<strong>&quot;护城河&quot;（Economic Moat）</strong> 是出现频率最高的词汇之一。它代表了企业抵御竞争、维持超额利润的能力——也是<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>选择投资标的时最重要的判断标准。</p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1993年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">首次系统性阐述护城河概念</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1999年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">详细分析<a href="/03_companies/可口可乐.html">可口可乐</a>的护城河</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2007年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">讨论护城河变窄的风险（报纸行业）</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2014年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">高资本回报率与护城河的关系</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2015年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">护城河是内在价值的驱动力</td></tr></tbody></table><hr><h2 id="一、什么是护城河" tabindex="-1">一、什么是护城河 <a class="header-anchor" href="#一、什么是护城河" aria-label="Permalink to &quot;一、什么是护城河&quot;">​</a></h2><p>&quot;护城河&quot;这个概念并非<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的发明，而是借鉴自冷兵器时代城堡防御系统的比喻。在投资语境中，它指的是企业长期保持竞争优势的结构性壁垒。</p><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1993年致股东信中首次系统性地阐述了这一概念：</p><blockquote><p>&quot;评估一项业务时最重要的标准是它的&#39;护城河&#39;——即企业抵御竞争的能力有多强……城堡周围是否有一条护城河？即使有，这条护城河是在变宽还是在变窄？&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1993年致股东信</p></blockquote><p><strong>2007年</strong>，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>给出了护城河最经典的定义：</p><blockquote><p>&quot;一家真正伟大的企业必须有持久的&#39;护城河&#39;——一种结构性的竞争优势，让竞争对手无法轻易模仿，从而保护投资者的高资本回报。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2007年致股东信</p></blockquote><hr><h2 id="二、按十年分块-护城河理念的演进" tabindex="-1">二、按十年分块：护城河理念的演进 <a class="header-anchor" href="#二、按十年分块-护城河理念的演进" aria-label="Permalink to &quot;二、按十年分块：护城河理念的演进&quot;">​</a></h2><h3 id="🏛️-合伙基金与早期-1956-1969" tabindex="-1">🏛️ 合伙基金与早期（1956-1969） <a class="header-anchor" href="#🏛️-合伙基金与早期-1956-1969" aria-label="Permalink to &quot;🏛️ 合伙基金与早期（1956-1969）&quot;">​</a></h3><p>这一时期<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>师从<a href="/04_people/本·格雷厄姆.html">格雷厄姆</a>，更关注&quot;净流动资产&quot;而非护城河。但他已在实践中运用了护城河思维——典型的例子是<a href="/03_companies/喜诗糖果.html">喜诗糖果</a>（See&#39;s Candies）：</p><blockquote><p>&quot;我们1972年收购喜诗时，年销售1600万磅糖果，税前利润约210万。现在喜诗年销售3100万磅，税前利润约8300万。这50年只涨了两次价，但护城河越来越宽。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2007年致股东信</p></blockquote><hr><h3 id="📈-转型期-1970-1989" tabindex="-1">📈 转型期（1970-1989） <a class="header-anchor" href="#📈-转型期-1970-1989" aria-label="Permalink to &quot;📈 转型期（1970-1989）&quot;">​</a></h3><p><strong>1985年</strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对护城河的理解已相当成熟：</p><blockquote><p>&quot;B夫人94岁还在干活，每天上班，NFM越做越大，Dillard进奥马哈都不敢卖家具和她竞争。这就是护城河——几十年如一日的坚持，把简单事情做到极致。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1985年致股东信</p></blockquote><p><strong>1988年</strong>首次买入<a href="/03_companies/可口可乐.html">可口可乐</a>，护城河分析是核心：</p><blockquote><p>&quot;可口可乐拥有全球最强大的消费品牌，其护城河来自消费者的品牌认知和习惯，这种优势几乎无法复制。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1988年致股东信</p></blockquote><p><strong>1987年</strong>股灾之后，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>揭示了护城河的本质：</p><blockquote><p>&quot;《财富》统计，过去十年，连续十年平均ROE超过20%，一千家大公司只有二十五家。大部分都是平淡无奇行业，卖普通商品，但就是能持续赚钱，就是把简单事情做到极致。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1987年致股东信</p></blockquote><hr><h3 id="🔍-体系化时期-1990-1999" tabindex="-1">🔍 体系化时期（1990-1999） <a class="header-anchor" href="#🔍-体系化时期-1990-1999" aria-label="Permalink to &quot;🔍 体系化时期（1990-1999）&quot;">​</a></h3><p><strong>1993年</strong>正式提出&quot;护城河&quot;概念，并分析了<a href="/03_companies/可口可乐.html">可口可乐</a>的护城河构成：</p><ul><li>消费者对品牌的情感认同</li><li>产品的习惯性消费</li><li>规模经济带来的成本优势</li><li>全球性的分销网络</li></ul><p><strong>1999年</strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在太阳城演讲中详细阐述了护城河的来源：</p><blockquote><p>&quot;关键问题是：是什么让一家企业值得拥有护城河？答案包括：它是一种消费者想要或需要的产品或服务；有定价权；被顾客认为是无可替代的；不受价格管制的约束。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1999年太阳城演讲</p></blockquote><p><strong>1996年</strong>：</p><blockquote><p>&quot;真正有护城河的企业，可以在不提价的情况下转嫁成本上涨，或者在成本下降时获得更多利润。而护城河狭窄的企业，只能被动应对竞争，利润空间被不断侵蚀。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，1996年致股东信</p></blockquote><hr><h3 id="⚖️-深化与警示-2000-2025" tabindex="-1">⚖️ 深化与警示（2000-2025） <a class="header-anchor" href="#⚖️-深化与警示-2000-2025" aria-label="Permalink to &quot;⚖️ 深化与警示（2000-2025）&quot;">​</a></h3><p><strong>2007年</strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对护城河变窄发出最明确的警告：</p><blockquote><p>&quot;报纸曾经是，美国几乎每个家庭每天都要读的。现在，报纸在许多家庭中已经可有可无。随着互联网的崛起，报纸的护城河已经基本消失。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2007年致股东信</p></blockquote><p><strong>2014年</strong>：</p><blockquote><p>&quot;真正持久的护城河，来自企业文化和组织能力，不只是产品本身。高资本回报率是护城河的财务体现——如果你能看到企业在很长时间里持续产生高ROE，这本身就是护城河的信号。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2014年致股东信</p></blockquote><p><strong>2015年</strong>：</p><blockquote><p>&quot;我们的投资收益，本质上来自于我们投资的企业持续创造超过资本成本的经济利润。这种超额回报的持续性，就是护城河。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2015年致股东信</p></blockquote><hr><h2 id="三、护城河的五大来源" tabindex="-1">三、护城河的五大来源 <a class="header-anchor" href="#三、护城河的五大来源" aria-label="Permalink to &quot;三、护城河的五大来源&quot;">​</a></h2><p>根据<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>历年论述，护城河主要来自：</p><ol><li><strong>无形资产</strong> — 品牌、专利、特许经营权（如可口可乐的品牌、《华盛顿邮报》的新闻公信力）</li><li><strong>转换成本</strong> — 顾客更换产品代价高昂（如GEICO的保险客户一旦熟悉流程就不愿换）</li><li><strong>网络效应</strong> — 用户越多越有价值（如美国运通的信用卡网络）</li><li><strong>成本优势</strong> — 流程、地点或规模带来的低成本（如B夫人的内布拉斯加家具城）</li><li><strong>高效规模</strong> — 在一定规模内具有成本优势，超出则反之（如区域性公用事业）</li></ol><hr><h2 id="四、护城河的动态变化" tabindex="-1">四、护城河的动态变化 <a class="header-anchor" href="#四、护城河的动态变化" aria-label="Permalink to &quot;四、护城河的动态变化&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>特别强调：<strong>护城河不是静态的</strong>。</p><blockquote><p>&quot;资本主义动力学保证，竞争对手会不断攻击高回报企业。任何护城河，只要没有持续的维护和加强，都会慢慢被侵蚀。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，2005年致股东信</p></blockquote><p><strong><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>检验护城河的终极标准：</strong></p><blockquote><p>&quot;我喜欢的企业，是那种如果让你去管理，你会愿意永久持有的。如果你不愿持有它一百年，那就不要持有一分钟。&quot;</p><p>——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a></p></blockquote><hr><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>说明</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>企业抵御竞争、维持超额利润的结构性壁垒</td></tr><tr><td><strong>五大来源</strong></td><td>无形资产、转换成本、网络效应、成本优势、高效规模</td></tr><tr><td><strong>本质</strong></td><td>持续创造超过资本成本的经济利润</td></tr><tr><td><strong>动态性</strong></td><td>护城河会变宽，也会消失，需要持续评估</td></tr><tr><td><strong>财务信号</strong></td><td>高ROE + 长期持续 = 护城河的财务体现</td></tr></tbody></table><hr><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该主题在致股东信中的关键原文出处年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=核心总结">1993年：核心总结</a> → <a href="/01_letters/1993年/翻译.html">/01_letters/1993年/翻译</a></li><li><a href="/search.html?q=核心总结">1999年：核心总结</a> → <a href="/01_letters/1999年/翻译.html">/01_letters/1999年/翻译</a></li><li><a href="/search.html?q=核心总结">2007年：核心总结</a> → <a href="/01_letters/2007年/翻译.html">/01_letters/2007年/翻译</a></li><li><a href="/search.html?q=核心总结">2014年：核心总结</a> → <a href="/01_letters/2014年/翻译.html">/01_letters/2014年/翻译</a></li><li><a href="/search.html?q=核心总结">2015年：核心总结</a> → <a href="/01_letters/2015年/翻译.html">/01_letters/2015年/翻译</a></li></ul><h2 id="相关主题" tabindex="-1">相关主题 <a class="header-anchor" href="#相关主题" aria-label="Permalink to &quot;相关主题&quot;">​</a></h2><ul><li><a href="./intrinsic-value.html">内在价值 (Intrinsic Value)</a> — 护城河是内在价值的重要驱动因素</li><li><a href="./circle-of-competence.html">能力圈 (Circle of Competence)</a> — 只投资你能理解护城河的企业</li><li><a href="./safety-margin.html">安全边际 (Safety Margin)</a> — 在护城河最宽时买入</li></ul>',60)])])}const q=e(r,[["render",h]]);export{c as __pageData,q as default};
